function validItem(item) {
  return item && typeof item === 'object' && !Array.isArray(item) &&
    typeof item.key === 'string' && item.key.length > 0 &&
    typeof item.label === 'string';
}

function applyShelfCommand(items, command) {
  if (!Array.isArray(items) || items.some((item) => !validItem(item))) {
    throw new TypeError('invalid items');
  }
  if (new Set(items.map((item) => item.key)).size !== items.length) {
    throw new RangeError('duplicate item key');
  }
  if (!command || typeof command !== 'object' || Array.isArray(command)) {
    throw new TypeError('invalid command');
  }

  if (command.type === 'clear') return [];

  if (command.type === 'remove') {
    if (typeof command.key !== 'string' || command.key.length === 0) {
      throw new TypeError('invalid remove command');
    }
    const index = items.findIndex((item) => item.key === command.key);
    if (index !== -1) items.splice(index, 1);
    return items;
  }

  if (command.type === 'put') {
    if (!validItem(command.item)) {
      throw new TypeError('invalid put command');
    }
    const replacement = { key: command.item.key, label: command.item.label };
    const index = items.findIndex((item) => item.key === replacement.key);
    if (index === -1) return items.concat(replacement);
    const result = items.slice();
    result[index] = replacement;
    return result;
  }

  throw new TypeError('unknown command type');
}

module.exports = applyShelfCommand;

