'use strict';

const assert = require('node:assert');
const applyShelfCommand = require('./solution');

assert.strictEqual(typeof applyShelfCommand, 'function');

const first = Object.freeze({ key: 'a', label: 'Alpha' });
const second = Object.freeze({ key: 'b', label: 'Beta' });
const items = Object.freeze([first, second]);

const replacement = Object.freeze({ key: 'a', label: 'Updated' });
const putExisting = Object.freeze({ type: 'put', item: replacement });
const replaced = applyShelfCommand(items, putExisting);
assert.deepStrictEqual(replaced, [{ key: 'a', label: 'Updated' }, { key: 'b', label: 'Beta' }]);
assert.notStrictEqual(replaced, items);
assert.strictEqual(replaced[1], second);
assert.deepStrictEqual(items, [first, second]);
assert.deepStrictEqual(putExisting, { type: 'put', item: replacement });

const appended = applyShelfCommand(items, { type: 'put', item: { key: 'c', label: 'Gamma' } });
assert.deepStrictEqual(appended, [first, second, { key: 'c', label: 'Gamma' }]);

const removed = applyShelfCommand(items, { type: 'remove', key: 'a' });
assert.deepStrictEqual(removed, [second]);
assert.strictEqual(removed[0], second);

const unchanged = applyShelfCommand(items, { type: 'remove', key: 'missing' });
assert.deepStrictEqual(unchanged, [first, second]);
assert.notStrictEqual(unchanged, items);
assert.deepStrictEqual(applyShelfCommand(items, { type: 'clear' }), []);
assert.deepStrictEqual(applyShelfCommand([], { type: 'clear' }), []);

for (const invalidItems of [null, {}, 'items', [{ key: '', label: 'x' }], [{ key: 'x', label: 2 }]]) {
  assert.throws(() => applyShelfCommand(invalidItems, { type: 'clear' }), TypeError);
}
assert.throws(
  () => applyShelfCommand([{ key: 'x', label: 'one' }, { key: 'x', label: 'two' }], { type: 'clear' }),
  RangeError
);
for (const command of [
  null,
  {},
  { type: 'unknown' },
  { type: 'put' },
  { type: 'put', item: { key: '', label: 'x' } },
  { type: 'put', item: { key: 'x', label: 1 } },
  { type: 'remove' },
  { type: 'remove', key: '' }
]) {
  assert.throws(() => applyShelfCommand([], command), TypeError);
}

